 function options(values,selected,label){return `<option value="">${label}</option>`+[...new Set(values)].sort((a,b)=>a.localeCompare(b)).map(v=>`<option value="${escape(v||'__missing')}" ${(v||'__missing')===selected?'selected':''}>${escape(v||'Sin informar')}</option>`).join('');}
 function periodLabel(value){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(value||''))return 'Sin período';const [year,month]=value.split('-').map(Number);return new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric'}).format(new Date(year,month-1,15));}
 const comparisonCache=new Map();
 function comparisonChoiceKey(){return state.currentId||state.fileName+'|'+state.filePeriod;}
